class UniversityStudent {
    // Instance variable: independent for every student
    private String studentName;
    private int rollNumber;

    // Static class variable: shared by every student
    public static String universityName = "Global Tech Institute";

    public UniversityStudent(String name, int roll) {
        this.studentName = name;
        this.rollNumber = roll;
    }

    public void displayStudentInfo() {
        System.out.println(studentName + " [Roll: " + rollNumber + "] @ " + universityName);
    }
}

public class Main {
    public static void main(String[] args) {
        UniversityStudent s1 = new UniversityStudent("Aarav", 101);
        UniversityStudent s2 = new UniversityStudent("Bhavna", 102);

        s1.displayStudentInfo();
        s2.displayStudentInfo();

        // Changing the single shared whiteboard:
        System.out.println("\n--- University rebrands ---");
        UniversityStudent.universityName = "Apex University of Technology";

        // Both students instantly reflect the updated shared name!
        s1.displayStudentInfo();
        s2.displayStudentInfo();
    }
}

