class ServerNode {
    private String serverId;
    private static int totalActiveServers = 0; // Shared counter

    public ServerNode(String id) {
        this.serverId = id;
        totalActiveServers++; // Increment shared whiteboard every time a server is born
        System.out.println("Booted node " + serverId + ". Total nodes: " + totalActiveServers);
    }

    public static int getTotalActiveServers() {
        return totalActiveServers;
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("Initial servers: " + ServerNode.getTotalActiveServers());

        ServerNode n1 = new ServerNode("us-east-1a");
        ServerNode n2 = new ServerNode("us-east-1b");
        ServerNode n3 = new ServerNode("eu-central-1");

        System.out.println("Final fleet count: " + ServerNode.getTotalActiveServers());
    }
}

