    public String getDeviceName() { return deviceName; }
    public static int getActiveCount() { return activeCount; }
}

public class Main {
    public static void main(String[] args) {
        Device d1 = new Device("Phone");
        Device d2 = new Device("Tablet");
        Device d3 = new Device("Laptop");
        System.out.println("Total active devices: " + Device.getActiveCount());
    }
}

class ProductPrice {
    private double basePrice;
    private static double taxRate = 0.05;

    public ProductPrice(double price) {
        this.basePrice = price;
    }

    public static void setTaxRate(double rate) {
        if (rate >= 0.0) {
            taxRate = rate;
        }
    }

    public static double getTaxRate() {
        return taxRate;
    }

    public double calculateTotalPrice() {
        return basePrice + (basePrice * taxRate);
    }
}

public class Main {
    public static void main(String[] args) {
        ProductPrice p = new ProductPrice(100.0);
        ProductPrice.setTaxRate(0.10);
        System.out.println("Updated price with 10% tax: $" + p.calculateTotalPrice());
    }
}

