class EmployeeCounter {
    private String empName;
    private double salary;
    private static double totalCompanyPayroll = 0.0;

    public EmployeeCounter(String name, double sal) {
        this.empName = name;
        this.salary = sal;
        totalCompanyPayroll += sal;
    }

    public static void resetPayroll() {
        totalCompanyPayroll = 0.0;
    }

    public static double getTotalPayroll() {
        return totalCompanyPayroll;
    }
}

public class Main {
    public static void main(String[] args) {
        EmployeeCounter e1 = new EmployeeCounter("A", 3000.0);
        EmployeeCounter e2 = new EmployeeCounter("B", 4500.0);
        System.out.println("Total company payroll: $" + EmployeeCounter.getTotalPayroll());
    }
}
